drills.solution:
import { createHmac, timingSafeEqual } from 'node:crypto';

const decodeObject = (part) => {
  try {
    const value = JSON.parse(Buffer.from(part, 'base64url').toString('utf8'));
    return value !== null && typeof value === 'object' && !Array.isArray(value) ? value : null;
  } catch {
    return null;
  }
};

const fail = (reason) => ({ ok: false, reason });

export function verifyJwt(token, secret, nowSeconds) {
  if (typeof token !== 'string') return fail('malformed');
  const parts = token.split('.');
  if (parts.length !== 3) return fail('malformed');
  const header = decodeObject(parts[0]);
  const payload = decodeObject(parts[1]);
  if (!header || !payload) return fail('malformed');
  if (header.alg !== 'HS256') return fail('algorithm');
  const expected = createHmac('sha256', secret).update(parts[0] + '.' + parts[1]).digest();
  const given = Buffer.from(parts[2], 'base64url');
  if (given.length !== expected.length || !timingSafeEqual(given, expected)) return fail('signature');
  if (typeof payload.exp !== 'number' || nowSeconds >= payload.exp) return fail('expired');
  return { ok: true, payload };
}

