export function createSessionStore({ newId, now, ttlMs }) {
  const sessions = new Map(); // id -> { userId, data, expiresAt }

  const live = (id) => {
    const session = sessions.get(id);
    if (!session) return null;
    if (now() >= session.expiresAt) {
      sessions.delete(id);
      return null;
    }
    return session;
  };

  const start = (userId, data) => {
    const id = newId();
    sessions.set(id, { userId, data, expiresAt: now() + ttlMs });
    return id;
  };

  return {
    create(data = {}) {
      return start(null, data);
    },
    get(id) {
      const session = live(id);
      return session ? { userId: session.userId, data: session.data } : null;
    },
    login(id, userId) {
      // TODO: this keeps the id the visitor had before logging in (session fixation). Rotate it.
      const session = live(id);
      if (!session) return start(userId, {});
      session.userId = userId;
      return id;
    },
    logout(id) {
      sessions.delete(id);
    },
  };
}

