  const sessions = new Map(); // id -> { userId, data, expiresAt }

  const live = (id) => {
    const session = sessions.get(id);
    if (!session) return null;
    if (now() >= session.expiresAt) {
      sessions.delete(id);
      return null;
    }
    return session;
  };

  const start = (userId, data) => {
    const id = newId();
    sessions.set(id, { userId, data, expiresAt: now() + ttlMs });
    return id;
  };

  return {
    create(data = {}) {
      return start(null, data);
    },
    get(id) {
      const session = live(id);
      return session ? { userId: session.userId, data: session.data } : null;
    },
    login(id, userId) {
      const old = live(id);
      sessions.delete(id);
      return start(userId, old ? old.data : {});
    },
    logout(id) {
      sessions.delete(id);
    },
  };
}

