export function createRefreshTokens({ newToken, now, ttlMs }) {
  const tokens = new Map(); // token -> { userId, expiresAt }

  const add = (userId) => {
    const token = newToken();
    tokens.set(token, { userId, expiresAt: now() + ttlMs });
    return token;
  };

  return {
    issue(userId) {
      return add(userId);
    },
    rotate(token) {
      // TODO: one-time use, families, reuse detection, expiry
      const entry = tokens.get(token);
      if (!entry) return { ok: false, reason: 'unknown' };
      return { ok: true, userId: entry.userId, token: add(entry.userId) };
