}

drills.solution:
export function createRefreshTokens({ newToken, now, ttlMs }) {
  const tokens = new Map(); // token -> { userId, family, used, expiresAt }
  const revokedFamilies = new Set();
  let nextFamily = 1;

  const add = (userId, family) => {
    const token = newToken();
    tokens.set(token, { userId, family, used: false, expiresAt: now() + ttlMs });
    return token;
  };

  return {
    issue(userId) {
      return add(userId, nextFamily++);
    },
    rotate(token) {
      const entry = tokens.get(token);
      if (!entry) return { ok: false, reason: 'unknown' };
      if (revokedFamilies.has(entry.family)) return { ok: false, reason: 'revoked' };
      if (entry.used) {
        revokedFamilies.add(entry.family);
        return { ok: false, reason: 'reuse' };
      }
      if (now() >= entry.expiresAt) return { ok: false, reason: 'expired' };
      entry.used = true;
      return { ok: true, userId: entry.userId, token: add(entry.userId, entry.family) };
    },
  };
}

